import { Router } from 'express';
import { registerUser, verifyOtp, loginUser, googleAuth, firebaseAuthLogin, registerRole, getMe, getSessions, revokeSession, } from '../controllers/authController.js';
import { authenticateToken } from '../middleware/authMiddleware.js';
const router = Router();
router.post('/register', registerUser);
router.post('/verify-otp', verifyOtp);
router.post('/login', loginUser);
router.post('/google', googleAuth);
router.post('/firebase-login', firebaseAuthLogin);
router.post('/register-role', registerRole);
router.get('/me', authenticateToken, getMe);
router.get('/sessions', authenticateToken, getSessions);
router.delete('/sessions/:sessionId', authenticateToken, revokeSession);
export default router;
